    private void back(){searchOptionsPage="";rememberTaskCatalog();if(route.equals("taskcatalog"))AlarmEditorSearchUi.hideKeyboard(this);if(route.equals("challenge")){alarm.pin=routinePinBefore;routineDraft=alarm.challenges();}if(route.equals("search")){closeSearch();return;}if(route.equals(searchTarget)){returnToSearch();return;}if(route.equals("snooze")&&snoozeOptions){snoozeOptions=false;render();return;}if(!route.equals("edit")){route=parentRoute();render();}else finishDraft();}
