    private void objectResult(int result,Intent data){
        String request=objectRequest,snapshot=objectRoutine;int index=objectIndex;objectRequest="";objectRoutine="";objectIndex=-2;
        if(result!=RESULT_OK||data==null||request.isEmpty()||!request.equals(data.getStringExtra("request")))return;
        try{
            if(!snapshot.equals(ChallengeRoutineJson.encode(routineDraft).toString())||index< -1)throw new IllegalArgumentException("This routine changed. Reopen the object settings.");
            ObjectTarget target=ObjectTargetJson.decode(new JSONObject(data.getStringExtra("objectTarget")));
            ChallengeRoutine.Task selected=new ChallengeRoutine.Task("Object recognition",1,0,MathSettings.LEGACY,null,JournalRule.DEFAULT,null,target);
            if(index==-1)routineDraft=routineDraft.add(selected);else{if(index>=routineDraft.tasks.size()||!routineDraft.tasks.get(index).type.equals("Object recognition"))throw new IllegalArgumentException("The object task changed.");routineDraft=routineDraft.replace(index,selected);}
            taskIndex=index;route="challenge";render();
        }catch(Exception invalid){Ui.toast(this,"Object target could not be applied. Reopen its settings and try again.");}
    }
