    private boolean practiceRetained(){String snapshot=ChallengeRoutineJson.encode(routineDraft).toString();if(!snapshot.equals(routinePracticeSnapshot)){routinePracticeState=null;routinePracticeSnapshot=snapshot;}if(routinePracticeState==null)return false;Bundle session=routinePracticeState.getBundle("session");return session!=null;}
    private void openRoutinePractice(){
        if(!editorResumed||!hasWindowFocus()||isFinishing()||isDestroyed()||!route.equals("challenge")||!routinePracticeRequest.isEmpty())return;
        practiceRetained();routinePracticeLaunch=ChallengeRoutineJson.encode(routineDraft).toString();routinePracticeRequest=UUID.randomUUID().toString();
        try{startActivityForResult(ChallengePracticeActivity.preview(this,routineDraft,routinePracticeRequest,routinePracticeState),ChallengePracticeActivity.PREVIEW);}
        catch(RuntimeException unavailable){routinePracticeRequest="";routinePracticeLaunch="";Ui.toast(this,"Routine preview could not open. Your draft is unchanged.");}
    }
    private void routinePracticeResult(int result,Intent data){
        String expected=routinePracticeRequest,snapshot=routinePracticeLaunch;routinePracticeRequest="";routinePracticeLaunch="";
        if(expected.isEmpty()||data==null||result!=RESULT_OK&&result!=RESULT_CANCELED)return;
        try{
            if(data.getData()!=null||data.getClipData()!=null||data.getSelector()!=null||!expected.equals(data.getStringExtra("request"))||!snapshot.equals(data.getStringExtra("routine"))||!snapshot.equals(ChallengeRoutineJson.encode(routineDraft).toString()))throw new IllegalArgumentException();
            Bundle state=data.getBundleExtra("practiceState");if(state==null||state.getBundle("session")==null)throw new IllegalArgumentException();
            android.os.Parcel size=android.os.Parcel.obtain();try{size.writeBundle(state);if(size.dataSize()>196608)throw new IllegalArgumentException();}finally{size.recycle();}
            ChallengePracticeSession restored=ChallengePracticeSession.open(this,snapshot,state.getBundle("session"),ChallengePracticeScreen.SUPPORTED);new PracticeCheckpoints(restored.run,state.getBundle("checkpoints"));
            routinePracticeSnapshot=snapshot;routinePracticeState=restored.finished()?null:new Bundle(state);route="challenge";routinePracticeReturn=true;
        }catch(RuntimeException invalid){Ui.toast(this,"Preview progress could not be retained. Your routine is unchanged.");}
        // Child results may precede onResume. Publish private state now, render only in the live UI.
        showRoutinePracticeReturn();
    }
    private void showRoutinePracticeReturn(){if(!routinePracticeReturn||!editorResumed||!hasWindowFocus()||isFinishing()||isDestroyed())return;routinePracticeReturn=false;render();}
