    private String taskDescription(){return switch(inspectedTask){case "Spoken phrase"->"Read a displayed English phrase aloud. Only the top on-device recognized text is matched. Installed offline English and Android 12 or newer are required; Math is always available. This is not a speaker or liveness check.";case "Musical note"->"Hum or play one named note and hold its actual pitch for 1.2 seconds. The target stays the same for this task. No instrument or voice identity is recognized; Math is always available.";case "Spin around"->"Hold a finger on each screen pad and turn your body once while keeping the phone upright. Rotation-vector readings, not shakes, fill the ring. Math is always available.";case "Camera light"->"Point the visible camera toward a bright room light or window and hold its measured image brightness. No photos are saved; Math is always available.";case "Light"->"Use the phone’s ambient-light sensor to hold a chosen brightness for two seconds. Camera and flashlight stay off; Math is always available.";case "Type code"->"Read the original angled code, then type its letters and digits. The code stays the same until this task is solved.";case "Pose"->"Raise both hands above your head and hold steady while the front camera can see your head, arms and hips. Math is always available.";case "Smile"->"Use the front camera to detect one steady smile. This checks expression, not identity or liveness. Math is always available.";case "Laughter"->AudioChallengeMode.LAUGHTER.detail();case "Loud sound"->AudioChallengeMode.LOUD.detail();case "Speak"->"Speak for about 2 seconds after tapping Listen. Alarm sound pauses while listening. This detects speech activity, not words or speaker identity.";case "Walk"->"Carry your phone while you walk. Only detected steps count.";case "Visual search"->"Find the moon with closed eyes. Later rounds use larger boards.";case "Jumping"->"Tap Jump to guide the orb over three hurdles per round. Cleared hurdles stay saved; Math is always available.";case "Counting"->"Count only the requested shape and type its total.";case "Tilt maze"->"Calibrate face-up, then tilt gently through the maze. Math is available if the sensor is unavailable.";case "Flags"->"Recognize a flag from an original pack of eight countries.";case "Memory"->"Match every pair of symbols.";case "Sequence"->"Watch the digits, then repeat them in order.";case "Mirror text"->"Read the mirrored phrase, then type it normally.";case "Dream journal"->"Save a dream or morning reflection before continuing. Entries stay in your private diary.";case "Retype"->"Type the morning phrase exactly as shown.";case "Shake"->"Complete the chosen number of deliberate shakes.";case "NFC"->"Scan your enrolled morning tag.";default->"Solve every addition round in this task.";};}
    private void taskAbout(LinearLayout body){Design.header(body,"How it works",this::back);Design.text(body,inspectedTask,20,600,Design.INK);Design.space(body,16);Design.text(body,taskDescription(),15,400,Design.MUTED);Design.fixedAction(body,"Back to task",()->go("task"));}
