    private void save(){if(templateOnly){returnDefaults();return;}if(alarm.backupSoundInvalid){saveError="Review backup sound settings in Snooze before saving.";render();return;}if(alarm.smartWakeInvalid){saveError="Review smart wake-up settings before saving.";render();return;}try{NextAlarmOverrides.draft(this,alarm,originalAlarm);}catch(IllegalArgumentException invalid){saveError=invalid.getMessage();render();return;}if(alarm.repeatInvalid){saveError="Review the repeat rule before saving.";render();return;}try{alarm.repeatRule.check(alarm);if(alarm.enabled&&alarm.repeatRule.custom()&&alarm.next(System.currentTimeMillis())<=0)throw new IllegalArgumentException("No future repeat occurrence is available. Review the anchor and skipped dates.");}catch(IllegalArgumentException invalid){saveError=invalid.getMessage();render();return;}if(alarm.bedtimeInvalid){saveError="Review this alarm’s bedtime reminder before saving.";render();return;}if(alarm.snoozeTotalInvalid){saveError="Review the total snooze time in Snooze before saving.";render();return;}if(alarm.excludedDatesInvalid){saveError="Review selected skipped dates or clear the selection.";render();return;}if(alarm.date!=null&&alarm.excludedDates.contains(alarm.date)&&alarm.enabled){saveError="The selected alarm date is excluded. Remove it from skipped dates or choose another run date.";render();return;}if(alarm.solarInvalid){saveError="Review sunrise time settings or choose Clock time.";render();return;}if(alarm.soundModeInvalid){saveError="Review sound playback mode before saving.";render();return;}if(alarm.timingInvalid){saveError="Review backup and timeout settings in Snooze before saving.";render();return;}if(alarm.inputsInvalid){saveError="Review flip and volume-key settings in Snooze before saving.";render();return;}if(alarm.dateInvalid){saveError="Choose a valid alarm date or clear it.";render();return;}if(alarm.enabled&&alarm.date!=null&&alarm.next(System.currentTimeMillis())<=0){saveError="That alarm date has passed. Choose a future date.";render();return;}if(alarm.enabled&&!AlarmScheduling.port.allowed(this)){ReportDialogs.show(new AlertDialog.Builder(this).setTitle("Allow exact alarms").setMessage("Android requires Alarms & reminders access to schedule this alarm. Your draft is preserved.").setPositiveButton("Open settings",(d,w)->startActivity(new Intent(android.provider.Settings.ACTION_REQUEST_SCHEDULE_EXACT_ALARM,Uri.parse("package:"+getPackageName())))).setNegativeButton("Keep editing",null));return;}
        if(alarm.challenges().randomCount==0&&alarm.challenges().tasks.stream().anyMatch(task->task.type.equals("NFC"))&&Prefs.text(this,"nfcTag","").isEmpty()){Ui.toast(this,"Enroll an NFC tag in Alarms → Alarm options before using this challenge.");return;}
        if(alarm.routineInvalid){Ui.toast(this,"Choose and save a valid challenge routine first.");return;}
        // Persist the guarded draft first; an unconfirmed scheduling marker survives interruption.
        try{alarm=AlarmSkips.edit(this,store,alarm,originalAlarm,originalExisted);originalAlarm=Alarm.read(alarm.json());originalExisted=true;WakeChecks.alarmEdited(this,store,alarm);if(!alarm.scheduleError.isEmpty()){saveError=alarm.scheduleError;render();return;}saveError="";finish();}catch(AlarmSkips.Changed changed){saveError=changed.getMessage();render();}catch(RuntimeException e){saveError="Alarm could not be saved or scheduled. Check alarm access and try again.";render();}
    }
    static String displayTime(android.content.Context c,Alarm a){if(a.solarInvalid)return "Review sunrise";if(a.solar!=null){long at=AlarmSkips.next(c,a);if(at>0)return RecordUi.clock(c,at,java.time.ZoneId.systemDefault());return "Sunrise";}return Design.clock(c,a.hour*60+a.minute);}
    static String toneName(String tone){return AlarmTones.name(tone);}
    private void relativeResult(int result,Intent data){String expected=relativeRequest;relativeRequest="";if(result!=RESULT_OK||data==null||expected.isEmpty()||!expected.equals(data.getStringExtra("request")))return;try{if(!RelativeAlarmTime.allowed(alarm)||!RelativeAlarmTime.identity(alarm).equals(data.getStringExtra("draft")))throw new IllegalArgumentException("The alarm draft changed. Reopen relative entry.");java.time.ZoneId zone=java.time.ZoneId.of(data.getStringExtra("zone"));RelativeAlarmTime proposal=new RelativeAlarmTime(data.getIntExtra("duration",-1),data.getLongExtra("wall",-1),data.getLongExtra("elapsed",-1),zone);proposal.check(System.currentTimeMillis(),android.os.SystemClock.elapsedRealtime(),java.time.ZoneId.systemDefault());if(proposal.target!=data.getLongExtra("target",-1))throw new IllegalArgumentException("The proposed time changed. Review it again.");alarm.hour=proposal.local.getHour();alarm.minute=proposal.local.getMinute();alarm.date=proposal.local.toLocalDate();alarm.dateInvalid=false;AlarmSkips.clear(alarm);goalNotice="One-time date and time copied. Save alarm to keep it.";saveError="";}catch(RuntimeException invalid){saveError=invalid.getMessage()==null?"Relative time could not be copied. Review it again.":invalid.getMessage();}render();}
    private void openNextOverride(){nextRequest=UUID.randomUUID().toString();try{startActivityForResult(NextAlarmOverrideActivity.edit(this,alarm,nextRequest),NextAlarmOverrideActivity.REQUEST);}catch(RuntimeException unavailable){nextRequest="";saveError="Next-alarm review could not open. Keep this draft and try again.";render();}}
    private void nextOverrideResult(int result,Intent data){String expected=nextRequest;nextRequest="";if(result!=RESULT_OK||data==null||expected.isEmpty()||!expected.equals(data.getStringExtra("request")))return;try{if(!AlarmRepeat.identity(alarm).equals(data.getStringExtra("draft")))throw new IllegalArgumentException("This alarm draft changed. Reopen Next alarm only.");Alarm candidate=Alarm.read(alarm.json());AlarmSkips.consumeSkip(candidate);NextAlarmOverride value=data.getBooleanExtra("undo",false)?null:NextAlarmOverride.decode(new JSONObject(data.getStringExtra("nextOverride")));candidate.setNextOverride(value);NextAlarmOverrides.draft(this,candidate,originalAlarm);alarm.setNextOverride(value);AlarmSkips.consumeSkip(alarm);saveError="";goalNotice=value==null?"Override removed from the draft. Save alarm to restore the ordinary schedule.":"One occurrence moved in this draft. Save alarm to apply it.";}catch(Exception invalid){saveError=invalid.getMessage()==null?"Review the next occurrence again before saving.":invalid.getMessage();}render();}
    private void openRepeat(){repeatRequest=UUID.randomUUID().toString();try{startActivityForResult(AlarmRepeatActivity.edit(this,alarm,repeatRequest),AlarmRepeatActivity.REQUEST);}catch(RuntimeException unavailable){repeatRequest="";saveError="Repeat settings could not open. Keep this draft and try again.";render();}}
    private void repeatResult(int result,Intent data){String request=repeatRequest;repeatRequest="";if(result!=RESULT_OK||data==null||request.isEmpty()||!request.equals(data.getStringExtra("request")))return;try{if(!AlarmRepeat.identity(alarm).equals(data.getStringExtra("draft")))throw new IllegalArgumentException("This alarm draft changed. Reopen Repeat rule.");AlarmRepeat rule=AlarmRepeat.decode(new JSONObject(data.getStringExtra("rule")));Set<Integer> days=AlarmRepeat.days(new JSONArray(data.getStringExtra("days")));Alarm candidate=Alarm.read(alarm.json());candidate.setRepeat(rule);candidate.days=new HashSet<>(days);if(candidate.date!=null&&!days.isEmpty())throw new IllegalArgumentException("Clear the one-time date before choosing repeat weekdays.");rule.check(candidate);boolean changed=!AlarmSkips.scheduleKey(alarm).equals(AlarmSkips.scheduleKey(candidate));if(changed&&(alarm.nextOverride!=null||alarm.nextOverrideInvalid))throw new IllegalArgumentException("Undo Next alarm only before changing the repeat rule.");alarm.setRepeat(rule);alarm.days=new HashSet<>(days);if(changed)AlarmSkips.clear(alarm);saveError="";goalNotice="Repeat draft copied. Save alarm to apply it.";}catch(Exception invalid){saveError=invalid.getMessage()==null?"Repeat settings could not be applied. Reopen their review.":invalid.getMessage();}render();}
    @Override protected void onActivityResult(int r,int result,Intent data){super.onActivityResult(r,result,data);if(r==ChallengePracticeActivity.PREVIEW){routinePracticeResult(result,data);return;}if(r==RandomChallengeActivity.REQUEST){randomResult(result,data);return;}if(r==NextAlarmOverrideActivity.REQUEST){nextOverrideResult(result,data);return;}if(r==AlarmRepeatActivity.REQUEST){repeatResult(result,data);return;}if(r==OBJECT_CONFIG){objectResult(result,data);return;}if(r==RelativeAlarmTimeActivity.REQUEST){relativeResult(result,data);return;}if(r==AlarmBedtimeActivity.REQUEST){String expected=bedtimeRequest;bedtimeRequest="";if(result==RESULT_OK&&data!=null&&!expected.isEmpty()&&expected.equals(data.getStringExtra("request")))try{alarm.bedtime=AlarmBedtime.decode(new JSONObject(data.getStringExtra("bedtime")));alarm.bedtimeInvalid=false;saveError="";render();}catch(Exception invalid){saveError="Review the bedtime reminder setting before saving.";render();}return;}if(r==AlarmExcludedDatesActivity.REQUEST){String expected=excludedRequest;excludedRequest="";if(result==RESULT_OK&&data!=null&&!expected.isEmpty()&&expected.equals(data.getStringExtra("request")))try{alarm.excludedDates=AlarmExcludedDates.read(new JSONArray(data.getStringExtra("dates")));alarm.excludedDatesInvalid=false;saveError="";render();}catch(JSONException invalid){saveError="Skipped dates could not be read. Reopen their settings.";render();}return;}if(r==PictureMatchActivity.ENROLL){pictureResult(result,data);return;}if(r==GoalAlarmTimeActivity.REQUEST){String expected=goalRequest;goalRequest="";if(result==RESULT_OK&&data!=null&&!expected.isEmpty()&&expected.equals(data.getStringExtra("request"))){try{int value=data.getIntExtra("minute",-1);GoalAlarmPlan.Snapshot plan=GoalAlarmPlan.load(this);if(value<0||value>=1440||value!=plan.time().minute||!plan.identity().equals(data.getStringExtra("plan"))||!java.time.ZoneId.systemDefault().getId().equals(data.getStringExtra("zone")))throw new IllegalArgumentException("Saved plan changed. Open Use sleep plan again.");alarm.hour=value/60;alarm.minute=value%60;goalNotice=alarm.solar==null?"Fixed time copied. Save alarm to keep it.":"Sunrise fallback copied. Save alarm to keep it.";saveError="";}catch(IllegalArgumentException invalid){saveError=invalid.getMessage();}render();}return;}if(r==SunriseTimeActivity.REQUEST){if(result==RESULT_OK&&data!=null&&!solarRequest.isEmpty()&&solarRequest.equals(data.getStringExtra("request"))){solarRequest="";try{int hour=data.getIntExtra("hour",-1),minute=data.getIntExtra("minute",-1);if(hour<0||hour>23||minute<0||minute>59)throw new JSONException("Invalid fallback time");SunriseSchedule value=data.getBooleanExtra("clock",false)?null:SunriseScheduleJson.decode(new JSONObject(data.getStringExtra("solar")));alarm.solar=value;alarm.solarInvalid=false;alarm.hour=hour;alarm.minute=minute;saveError="";}catch(Exception invalid){saveError="Sunrise settings could not be read. Open Time basis to review them.";}render();}else solarRequest="";return;}if(r==343){qrResult(result,data);return;}if(r==AlarmToneImport.REQUEST||r==1){if(toneScreen!=null)toneScreen.result(result,data);return;}}
